import echarts from 'echarts';
require('echarts/theme/macarons'); // echarts theme

export default {
  name: 'PieChart',
  props: {
    className: {
      type: String,
      default: 'pieChart'
    },
    width: {
      type: String,
      default: '100%'
    },
    height: {
      type: String,
      default: '175px'
    },
    titleText: {
      type: String,
      default: '检修计划率'
    },
    seriesData: {
      type: Array,
      default: null
    }
  },
  data: function data() {
    return {
      chart: null,
      colors: ['#62C5E5', '#EFB56D', '#6ECAA2', '#F1A0BB', '#BEC140', '#7FA2B6', '#E9BB30', '#A197DF', '#7F9CD6', '#F18B34'],
      timer: null // 用于存储定时任务
    };
  },
  watch: {
    seriesData: {
      handler: function handler() {
        this.setOptions();
      },
      deep: true
    }
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      _this.initChart();
    });
  },
  beforeDestroy: function beforeDestroy() {
    if (!this.chart) {
      return;
    }
    // 清除定时任务
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    this.chart.dispose();
    this.chart = null;
  },
  methods: {
    initChart: function initChart() {
      var _this2 = this;
      this.chart = echarts.init(this.$refs['pieChart'], 'macarons');
      this.setOptions();
      // 初始化定时任务
      this.startTimer();
      // 监听鼠标悬停事件
      this.chart.on('mouseover', function (v) {
        if (v.dataIndex !== 0) {
          // 暂停定时任务
          _this2.pauseTimer();
          // 隐藏定时任务的提示
          _this2.chart.dispatchAction({
            type: 'hideTip',
            seriesIndex: 0,
            dataIndex: 0
          });
          // 取消高亮定时任务的项
          _this2.chart.dispatchAction({
            type: 'downplay',
            seriesIndex: 0,
            dataIndex: 0
          });
        }
      });

      // 监听鼠标移出事件
      this.chart.on('mouseout', function () {
        // 恢复定时任务
        _this2.startTimer();
      });
    },
    startTimer: function startTimer() {
      var _this3 = this;
      if (!this.timer) {
        this.timer = setInterval(function () {
          _this3.chart.dispatchAction({
            type: 'showTip',
            seriesIndex: 0,
            dataIndex: 0
          });
          _this3.chart.dispatchAction({
            type: 'highlight',
            seriesIndex: 0,
            dataIndex: 0
          });
        }, 2000);
      }
    },
    pauseTimer: function pauseTimer() {
      if (this.timer) {
        clearInterval(this.timer);
        this.timer = null;
      }
    },
    setOptions: function setOptions() {
      this.chart.setOption({
        color: this.colors,
        title: {
          text: this.titleText,
          show: true,
          subtext: '',
          left: 'left',
          top: '0%',
          textStyle: {
            color: '#000',
            fontSize: 15,
            fontFamily: 'Arial'
          }
        },
        tooltip: {
          trigger: 'item'
        },
        legend: {
          top: '90%',
          left: 'center',
          show: false // 不展示图例
        },
        series: [{
          data: this.seriesData,
          type: 'pie',
          radius: ['45%', '55%'],
          avoidLabelOverlap: false,
          itemStyle: {
            borderRadius: 10,
            borderColor: '#fff',
            borderWidth: 2
          },
          label: {
            show: false,
            position: 'center'
          },
          emphasis: {
            label: {
              show: true,
              fontSize: 20,
              fontWeight: 'bold',
              formatter: function formatter(data) {
                return data.percent + '%';
              }
            }
          },
          labelLine: {
            show: false
          }
        }]
      });
    }
  }
};
